    {
      "indicator": "Preço (close)",
      "reading": "14.34",
      "interpretation": "Fechamento abaixo da MM20/EMA9 → retração de curto prazo dentro de tendência maior positiva."
    },
    {
      "indicator": "MM20",
      "reading": "14.6375",
      "interpretation": "Média curta acima da MM50/MM200 (ordem altista), mas preço agora abaixo — resistência de curto prazo."
    },
    {
      "indicator": "MM50",
      "reading": "14.0580",
      "interpretation": "Suporte de médio prazo próximo; perda sustentada abriria teste da MM200."
    },
    {
      "indicator": "MM200",
      "reading": "13.7648",
      "interpretation": "Suporte estrutural de longo prazo; tendência de fundo ainda positiva enquanto acima deste nível."
    },
    {
      "indicator": "EMA9",
      "reading": "14.6379",
      "interpretation": "Reage rápido ao preço; preço abaixo da EMA9 confirma fraqueza de curtíssimo prazo."
    },
    {
      "indicator": "EMA21",
      "reading": "14.5418",
      "interpretation": "EMA21 acima do preço — reforça a leitura de correção de curto prazo."
    },
    {
      "indicator": "MACD",
      "reading": "MACD 0.1557 / Signal 0.2162 / Hist -0.0605",
      "interpretation": "MACD ainda positivo mas abaixo da linha de sinal; histograma negativo indica perda de momentum comprador."
    },
    {
      "indicator": "Bandas de Bollinger",
      "reading": "BB_lower 13.7070 / BB_mid 14.6375 / BB_upper 15.5680",
      "interpretation": "Bandas alargadas (volatilidade elevada). Preço entre mid e lower — room para suporte antes de queda mais forte."
    },
    {
      "indicator": "RSI14",
      "reading": "48.2049",
      "interpretation": "Neutro (não há sobrecompra/sobrevenda); não sinaliza reversão imediata."
    },
    {
      "indicator": "Volume (última sessão)",
      "reading": "9,997,400",
      "interpretation": "Volume moderado, inferior aos picos que acompanharam o rali de maio — o recuo atual tem baixa convicção em volume."
    }
  ]
}
